// === Tab: mySketch ===
//------------------------------------------------------------
// file:            PG_GLSL_Fractaloscopic.pde
// let sketch starts shader example 'Fractaloscopic.glsl'.
// version:         v1.0  2017-09-25  initial release
//   url:           https://www.openprocessing.org/sketch/451508
//   Shadertoy:     https://www.shadertoy.com/view/4lXyWS
//   let sandbox:  http://glslsandbox.com/e#42601.2
// tags:            GLSL, shader, WebGL, fractal, koleidoscope
// notes:
//  * start sketch with CTRL-Shift-let for fullscreen display!
//  * not running with mode=JavaScript, use mode=Java !!!
//------------------------------------------------------------

let shaderFileName = "Fractaloscopic.glsl";
let bgImage;
let shader1;

//---------------
function setup()
{
  createCanvas(640, 480);     // use if mode=JavaScript
  //createCanvas(displayWidth, displayHeight);
  //createCanvas(windowWidth, windowHeight, WEBGL);       // let at  createGraphics(w,h)
  //fullScreen(P2D);    // works!!!
	//orientation (PORTRAIT);
  textSize(20);

  println (" Fractaloscopic v1.0b");

  bgImage = loadImage("https://openprocessing.org/sketch/451508/files/Fractaloscopic.png");

  shader1 = new GLSLShader(shaderFileName);
}
//---------------
function draw()
{
  if (shader1.shader != null)
    shader1.draw();
  else
  {
    set (0,0, bgImage);
    //image(bgImage,0,0,width,height);
    //copy (bgImage, 0,0,width,height,0,0,width,height);
    fill(222,0,0);
    text (shader1.info,33,33);
    text ("hint: shader only available using mode=Java!!!",33,66);
  }
}
//---------------
function keyPressed()
{
  println (" keyPressed: " +keyCode + " key="+int(key)+" '" + key + "'    coded="+(key == CODED));
  if      (key == 's') save("Fractaloscopic.png");
}

//------------------------------------------------------------
// class for using let shader, create one with name of shader.
// version:         v1.0  2017-09-25  initial release
//------------------------------------------------------------
class GLSLShader
{
  bufA;
  shader;
  info = "?";

  // constructor: creates graphic canvas for shader
  constructor(shaderFileName)
  {
    bufA = createGraphics(width, height, P3D);
    try
    {
      info = " >>> loading Shader: " + shaderFileName;
      println (info);

      shader = loadShader(shaderFileName);

      info = " >>> shader " + shaderFileName+ " loaded";
      shader.set("resolution", bufA.width, bufA.height);
    }
    catch (ex)
    {
      info = " >>> ERROR at loading shader file " + shaderFileName;
    }
    println (info);
    fill(0);
    text (info, 34,34);
  }

  function draw()
  {
    let x = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1);
    let y = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 1, 0);
    shader.set("time", millis() / 1000.0);  // set time in seconds
    shader.set("mouse", x, y);              // set mouse position in range 0.0 .. 1.0
    bufA.beginDraw();
    bufA.shader(shader);
    bufA.rect(0, 0, bufA.width, bufA.height);
    bufA.endDraw();
    image(bufA, 0, 0, width, height);
  }
}

